WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT s.id, s.account_id, s.is_flagged, s.prev_txn_time, s.new_group_flag, s.island_id, (SELECT AVG(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS avg_transaction_amount FROM sessionized s ORDER BY island_id DESC NULLS LAST;
